/**
 * Route segments, typed the way they actually behave at runtime.
 *
 * expo-router's `useSegments()` is typed from `.expo/types/router.d.ts`, which
 * is generated by the dev server and is gitignored. On a machine that has run
 * the app the union is wide and indexing past `[0]` type-checks; in a clean
 * checkout — CI — the file is absent, the fallback types the result as the
 * 1-tuple `[string]`, and every `segments[1]` becomes "no element at index 1".
 *
 * That made `tsc` give different answers locally and in CI, which is the real
 * defect: a typecheck that depends on a build artifact proves nothing. The
 * runtime value is a variable-length array of path segments, so that is what
 * this returns. Route *names* are still checked wherever they are typed as
 * `Href`; this only loosens positional indexing.
 */
import { useSegments } from "expo-router";

export function useRouteSegments(): string[] {
  return useSegments() as unknown as string[];
}
